CREATE TABLE IF NOT EXISTS bridge_reward_catalog (id VARCHAR(40) PRIMARY KEY, name VARCHAR(120) NOT NULL, image VARCHAR(100) NOT NULL, enabled TINYINT NOT NULL DEFAULT 1, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_reward_rules (kind VARCHAR(20) PRIMARY KEY, catalog_id VARCHAR(40) NOT NULL, FOREIGN KEY(catalog_id) REFERENCES bridge_reward_catalog(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_reward_pool (catalog_id VARCHAR(40) PRIMARY KEY, FOREIGN KEY(catalog_id) REFERENCES bridge_reward_catalog(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_award_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, course_id VARCHAR(40) NOT NULL, lesson_id VARCHAR(40) NULL, award_key VARCHAR(100) NOT NULL, kind VARCHAR(20) NOT NULL, catalog_id VARCHAR(40) NOT NULL, name VARCHAR(120) NOT NULL, image VARCHAR(100) NOT NULL, label VARCHAR(120) NOT NULL, awarded_at BIGINT NOT NULL, active TINYINT NOT NULL DEFAULT 1, UNIQUE KEY one_award(user_id,award_key), FOREIGN KEY(user_id) REFERENCES bridge_users(id), FOREIGN KEY(course_id) REFERENCES bridge_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_features (name VARCHAR(40) PRIMARY KEY, version INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
